import React from 'react';
import { Users, Activity, MapPin, GraduationCap, Accessibility, Apple, ClipboardCheck, Star } from 'lucide-react';
import { useQuery } from 'react-query';
import { Bar, Doughnut } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement,
} from 'chart.js';
import api from '../../services/api';
import StatCard from './StatCard';
import LoadingSpinner from '../Common/LoadingSpinner';
import './Dashboard.css';

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement
);

const Dashboard = () => {
  const { data: dashboardData, isLoading } = useQuery(
    'dashboard',
    () => api.get('/dashboard/').then(res => res.data),
    { refetchInterval: 300000 }
  );

  if (isLoading) return <LoadingSpinner />;
  if (!dashboardData) return <div>Failed to load dashboard data</div>;

  const colors = {
    primary: '#2E2C6E',
    secondary: '#1C7EC4',
    success: '#2F9E68',
    warning: '#B9793A',
    danger: '#C94B4B',
  };

  const disabilityData = {
    labels: dashboardData.children_by_disability?.map(d => d.disability_type || 'Unspecified') || [],
    datasets: [{
      data: dashboardData.children_by_disability?.map(d => d.count) || [],
      backgroundColor: ['#2E2C6E', '#1C7EC4', '#B9793A', '#2F9E68', '#C94B4B', '#7C6FD1'],
      borderWidth: 0,
    }]
  };

  return (
    <div className="dashboard fade-in">
      <div className="dashboard-header">
        <div>
          <h1 className="dashboard-title">Dashboard</h1>
          <p className="dashboard-subtitle">Program overview and key performance indicators</p>
        </div>
      </div>

      <div className="stats-grid">
        <StatCard icon={Users} label="Total Children" value={dashboardData.total_children} color={colors.primary} />
        <StatCard icon={Activity} label="Active Children" value={dashboardData.active_children} color={colors.success} />
        <StatCard icon={MapPin} label="Outreach Clinics" value={dashboardData.outreach_clinics?.total || 0} color={colors.secondary} />
        <StatCard icon={GraduationCap} label="Caregivers Trained" value={dashboardData.training?.caregivers_trained || 0} color={colors.warning} />
        <StatCard icon={Accessibility} label="Devices Distributed" value={dashboardData.devices_distributed?.total || 0} color={colors.secondary} />
        <StatCard icon={Apple} label="Nutrition Support" value={dashboardData.nutrition?.children_supported || 0} color={colors.success} />
        <StatCard icon={ClipboardCheck} label="Assessments" value={dashboardData.assessments?.total || 0} color={colors.primary} />
        <StatCard icon={Star} label="Success Stories" value={dashboardData.success_stories || 0} color={colors.warning} />
      </div>

      <div className="charts-grid">
        <div className="chart-card">
          <h3>Children by Disability Type</h3>
          <div className="chart-container">
            <Doughnut data={disabilityData} options={{ responsive: true, plugins: { legend: { position: 'bottom' } }, cutout: '60%' }} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
